from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('P04','Un geyser: associazione e previsione','Durata dell’eruzione, intervalli e valutazione su eventi separati')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P04',i,b)
m.sezione_nuova('Fonte, bersaglio e separazione dei dati')
p('Definire il bersaglio prima del modello',
'''Il dataset faithful contiene 272 coppie di durata dell’eruzione e attesa alla successiva, espresse in minuti. Il progetto esamina se la durata migliori la previsione dell’attesa rispetto a una previsione costante. La durata completa è disponibile soltanto al termine dell’eruzione, mentre l’estratto non fornisce date e protocollo dettagliato dell’origine dei tempi. Un’applicazione operativa dovrebbe quindi verificare anche se l’attesa sia misurata dall’inizio o dalla fine dell’evento, traducendo il bersaglio nel tempo residuo effettivamente disponibile al momento della previsione.''',tikz=d('D01',linea(.5,2.3,7,2.3)+rect(1,1.7,3.2,2.9)+n(2.1,1.1,'Eruzione',w=2.7)+linea(3.2,3.3,3.2,4.2,'Quantum')+n(3.2,5,'Durata completa disponibile',w=3.7,size=11.5)+n(6,1.1,'Evento seguente',w=2.7,size=11.5)+linea(6,1.7,6,2.9,'Quantum')+a(3.5,3.5,5.8,3.5,'Quantum')+n(5.1,4.3,'Tempo residuo',w=2.7,size=11.5)),richiamo='Il bersaglio operativo richiede un’origine temporale coerente con l’informazione disponibile.',fonti='R datasets: faithful; Azzalini e Bowman, 1990',origine='P04:1–4')
p('La fonte conserva arrotondamenti e limiti storici',
'''La tabella riproduce i valori distribuiti con R e conserva un identificativo di riga, costruito per rendere ripetibile la separazione dei dati. La documentazione segnala arrotondamenti nei tempi, per cui coppie numericamente uguali possono rappresentare eventi distinti. Il controllo confronta i valori con faithful e verifica positività e identificativi, evitando cancellazioni automatiche. L’assenza delle date impedisce di costruire una vera verifica prospettica della stabilità nel tempo e limita l’interpretazione del test a una generalizzazione interna sotto scambiabilità.''',destra='Il dataset storico riguarda Old Faithful nello Yellowstone. Le unità in minuti e le convenzioni della fonte devono essere mantenute nel modello. Un risultato ottenuto su questo estratto richiederebbe nuove osservazioni cronologiche e verifiche del protocollo prima di sostenere una prestazione operativa attuale.',richiamo='L’uguaglianza di valori arrotondati va distinta dalla duplicazione accidentale di una registrazione.',origine='P04:3–6')
p('Una separazione condivisa prima dell’esplorazione',
'''Il piano conservato assegna 190 eventi all’insieme di adattamento e 82 a quello di verifica, mantenendo gli identificativi delle righe. L’esplorazione, la stima dei coefficienti e la costruzione della previsione costante utilizzano soltanto i 190 eventi iniziali. Gli 82 eventi separati vengono impiegati per valutare le procedure già definite. Poiché la divisione è casuale e manca una cronologia, l’esperimento valuta la generalizzazione entro una popolazione di eventi considerata scambiabile, senza simulare necessariamente le condizioni di una previsione futura.''',tikz=d('D02',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'272 eventi identificati',w=6)+a(2,2.1,2,3)+a(5.4,2.1,5.4,3,'Quantum')+rect(.4,3.2,3.5,4.8)+n(1.95,4,'190: adattamento',w=2.8,size=12)+rect(3.9,3.2,7,4.8,'Quantum')+n(5.45,4,'82: verifica',w=2.8,size=12)+n(3.7,5.7,'Piano fisso; nessun evento appartiene a entrambi.',w=6.8,size=11)),richiamo='La separazione riguarda tutte le decisioni che possono utilizzare l’informazione della risposta.',origine='P04:5,7,18')
c=estratto('P04','separazione',"d <- read.csv('dati/progetti/faithful.csv')\ns <- read.csv(paste0('dati/progetti/',\n 'piani_ricampionamento/faithful_split.csv'))\nd <- merge(d,s,by='row_id',sort=TRUE)\ntr <- d[d$set=='train',]\nte <- d[d$set=='test',]\nstopifnot(nrow(tr)==190,nrow(te)==82,\n !length(intersect(tr$row_id,te$row_id)))")
p('Identificativi e separazione verificabile',
'''La separazione viene applicata mediante l’identificativo, così che un ordinamento diverso della tabella non cambi l’appartenenza degli eventi. I controlli sul piano completo, eseguiti nello script integrale, verificano unicità e copertura di tutti gli identificativi prima dell’unione. Il frammento controlla poi numerosità e disgiunzione dei due insiemi. La riproduzione della procedura dipende dal piano salvato, mentre un semplice seme casuale condiviso fra linguaggi non garantirebbe la medesima assegnazione delle righe.''',codice=c,richiamo='Un piano esplicito conserva l’assegnazione degli eventi indipendentemente dall’ordinamento e dal generatore casuale.',origine='P04:5,11,25')
m.sezione_nuova('Associazione nel campione di adattamento')
p('La relazione mostra due addensamenti',
'''Il grafico delle 190 coppie di adattamento mostra una relazione crescente e due addensamenti nella durata e nell’attesa. Questi gruppi visivi suggeriscono una struttura che merita approfondimento, pur senza identificare automaticamente due stati fisici del sistema idrotermale. Una retta globale riassume insieme la separazione fra gli addensamenti e la variazione interna a ciascuno. La sua pendenza dovrà quindi essere interpretata come sintesi dell’associazione nel campione, verificando successivamente quanto differisca dalle pendenze entro intervalli di durata.''',figura='P04/F01',didascalia='Coppie del solo insieme di adattamento. La scala dell’attesa segue la variabile pubblicata nella fonte.',richiamo='La geometria del campione orienta l’interpretazione della pendenza prima della sua verifica inferenziale.',origine='P04:8')
p('La distribuzione delle durate completa il confronto',
'''L’istogramma rende esplicita la scarsa densità di eventi nella regione intermedia fra i due addensamenti. La posizione della retta in quella regione dipende dal modello lineare e riceve un sostegno osservativo minore rispetto alle zone più popolate. Gli intervalli delle barre sono fissati in quarti di minuto, mantenendo la scala e gli arrotondamenti della fonte. La lettura congiunta di istogramma e diagramma di dispersione permette di distinguere una relazione osservata diffusamente da una connessione sostenuta soprattutto da gruppi separati.''',figura='P04/F02',didascalia='Distribuzione delle durate nei 190 eventi di adattamento; intervalli di ampiezza 0,25 minuti.',richiamo='La densità dei predittori determina dove la relazione riceve maggiore sostegno empirico.',origine='P04:9')
p('La pendenza misura un’associazione media',
'''La regressione collega l’attesa alla durata mediante una retta e un errore di media condizionata nulla. La pendenza stimata è circa 10,898 minuti di attesa per ogni minuto aggiuntivo di durata, mentre il coefficiente di determinazione è circa 0,819. Il coefficiente descrive l’associazione nella specificazione adottata e non identifica l’effetto di un intervento capace di prolungare un’eruzione. L’interpretazione fisica richiede un modello delle condizioni comuni che determinano le due variabili.''',formula=r'Y_i=\alpha+\beta x_i+\varepsilon_i,\qquad E(\varepsilon_i\mid x_i)=0\\\widehat\beta=\frac{\sum_i(x_i-\overline x)(y_i-\overline y)}{\sum_i(x_i-\overline x)^2}',destra='La pendenza ha unità min/min, pur essendo numericamente adimensionale come rapporto di tempi. Esplicitare le due grandezze evita di trattarla come una variazione percentuale o come una proprietà universale del sistema.',richiamo='L’interpretazione della pendenza conserva risposta, predittore e dominio del campione utilizzato.',origine='P04:10–12')
p('La covarianza HC3 considera varianze differenti',
'''La covarianza HC3 mantiene la stima OLS e pesa i residui attraverso la leva delle osservazioni. Il fattore uno meno la leva corregge la riduzione del residuo associata a punti che influenzano maggiormente il proprio adattamento. La formula ammette varianze diverse sotto ipotesi di indipendenza e regolarità. Non rappresenta invece automaticamente la dipendenza fra eventi consecutivi o gruppi non osservati, per i quali servirebbe una struttura di covarianza coerente con il disegno.''',formula=r'h_i=x_i^T(X^TX)^{-1}x_i\\\widehat V_{HC3}=(X^TX)^{-1}X^T\operatorname{diag}\!\left(\frac{\widehat e_i^2}{(1-h_i)^2}\right)X(X^TX)^{-1}',tikz=d('D03',rect(.5,.5,6.9,1.8)+n(3.7,1.15,'Residuo e leva di ogni evento',w=6)+a(3.7,2,3.7,2.6)+rect(.5,2.8,6.9,4.1,'Quantum')+n(3.7,3.45,r'$\widehat e_i^2/(1-h_i)^2$',size=16)+a(3.7,4.3,3.7,4.9)+n(3.7,5.5,'Covarianza della stessa stima OLS',w=6.7,size=11.5)),richiamo='Una covarianza robusta risponde a una forma dichiarata di deviazione dalle ipotesi classiche.',fonti='MacKinnon–White; statsmodels, HC3_se',origine='P04:13')
p('Confrontare gli intervalli della pendenza',
'''L’intervallo t classico al 95% va da circa 10,161 a 11,635, mentre la costruzione HC3 va da circa 10,188 a 11,608 minuti per minuto. Nel secondo caso si utilizza lo stesso quantile t con 188 gradi di libertà come approssimazione dichiarata. Le ampiezze risultano simili in questo campione, senza che ciò costituisca una prova di omoschedasticità. La vicinanza fra le due costruzioni documenta soltanto una sensibilità limitata alla variante di covarianza effettivamente esaminata.''',figura='P04/F09',didascalia='Stima OLS comune e due intervalli della pendenza. Per HC3 il riferimento t è approssimativo.',richiamo='La concordanza fra due procedure viene interpretata entro le ipotesi e le varianti considerate.',origine='P04:12–13')
m.sezione_nuova('Incertezza della media e di un evento')
p('L’incertezza di un nuovo evento',
'''L’intervallo della media descrive l’incertezza sulla posizione della retta a una durata fissata. Per un nuovo evento si aggiunge la variabilità residua individuale, che compare nella formula attraverso il termine uno sotto radice. Entrambe le costruzioni adottano il modello classico omoschedastico e la stessa varianza residua. La covarianza HC3 della pendenza non viene trasformata automaticamente in un intervallo predittivo robusto, poiché quest’ultimo richiederebbe anche un modello della distribuzione del nuovo errore.''',formula=r'h_0=x_0^T(X^TX)^{-1}x_0\\IC_{media}:\ \widehat y_0\pm t\,s\sqrt{h_0},\qquad IP:\ \widehat y_0\pm t\,s\sqrt{1+h_0}',tikz=d('D04',linea(.8,3,6.7,3)+linea(1,1.8,1,4.2,'Quantum')+linea(6.4,1.8,6.4,4.2,'Quantum')+linea(2.7,2.4,2.7,3.6,'Classical')+linea(4.7,2.4,4.7,3.6,'Classical')+n(3.7,1,'Nuovo evento: fascia più ampia',w=6.5,size=11.5)+n(3.7,4.6,'Media condizionata: fascia interna',w=6.5,size=11.5)+n(3.7,5.8,'Stesso livello nominale, quantità differenti',w=6.6,size=11)),richiamo='La quantità oggetto dell’intervallo deve essere definita prima di interpretarne l’ampiezza.',origine='P04:14,26–27')
p('Le due fasce vengono lette sulla stessa scala',
'''La fascia verde segue l’incertezza della media condizionata, mentre quella viola rappresenta il nuovo evento sotto le ipotesi classiche. Entrambe si allargano allontanandosi dalla durata media del campione, poiché cresce la leva del punto di previsione. La fascia individuale rimane più ampia per il contributo della variabilità residua. Il disegno viene limitato al dominio delle durate osservate nel campione di adattamento, entro il quale restano comunque zone poco popolate e assunzioni di forma che devono essere discusse.''',figura='P04/F03',didascalia='Verde: intervallo della media; viola: intervallo predittivo individuale. Costruzioni classiche al 95%.',richiamo='Una fascia stretta intorno alla retta non implica una previsione individuale altrettanto precisa.',origine='P04:15')
p('I residui precedono l’interpretazione predittiva',
'''Il grafico dei residui rispetto alle attese stimate esamina la forma della relazione e la dispersione rimasta attorno alla retta. Strutture sistematiche potrebbero suggerire curvature, gruppi o variazioni di varianza, mentre punti isolati richiederebbero un controllo della fonte. La diagnosi resta confinata ai dati di adattamento. Le proprietà algebriche dei residui OLS, fra cui l’ortogonalità ai predittori, non garantiscono da sole la forma distributiva dell’errore futuro né la stabilità della relazione fra campagne osservative differenti.''',figura='P04/F04',didascalia='Residui dei 190 eventi usati per stimare la retta. Il riferimento tratteggiato indica residuo nullo.',richiamo='La diagnosi del modello interpreta la struttura residua prima della valutazione sui dati separati.',origine='P04:16')
m.sezione_nuova('Valutazione su eventi separati')
p('La previsione costante usa soltanto l’adattamento',
'''La procedura di riferimento assegna a ogni evento di verifica la media dell’attesa calcolata sui 190 eventi di adattamento, circa 70,479 minuti. Questa scelta stabilisce quanto si guadagni utilizzando la durata rispetto a una previsione priva di predittori. Impiegare la media degli 82 eventi di verifica introdurrebbe informazione della risposta proprio nel riferimento che si intende valutare. Entrambe le procedure vengono quindi definite prima del confronto finale e misurate sulle stesse osservazioni.''',formula=r'\widehat y_i^{(0)}=\overline y_{train},\qquad \widehat y_i^{(1)}=\widehat\alpha+\widehat\beta x_i',tikz=d('D05',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Dati di adattamento: media e coefficienti',w=6,size=11.5)+a(2,2.1,2,3)+a(5.4,2.1,5.4,3,'Quantum')+rect(.4,3.2,3.5,4.8)+n(1.95,4,'Previsione costante',w=2.8,size=11.5)+rect(3.9,3.2,7,4.8,'Quantum')+n(5.45,4,'Previsione lineare',w=2.8,size=11.5)+n(3.7,5.7,'Confronto sugli stessi 82 eventi separati',w=6.7,size=11.5)),richiamo='Il riferimento predittivo deve rispettare gli stessi vincoli informativi del modello esaminato.',origine='P04:17–18,28')
c=estratto('P04','previsione',"d <- read.csv('dati/progetti/faithful.csv')\ns <- read.csv(paste0('dati/progetti/',\n 'piani_ricampionamento/faithful_split.csv'))\nd <- merge(d,s,by='row_id')\ntr <- d[d$set=='train',]; te <- d[d$set=='test',]\nf <- lm(waiting_min~eruption_min,tr)\npred <- predict(f,te)\nsqrt(mean((te$waiting_min-pred)^2))")
p('La misura dell’errore mantiene il campione separato',
'''Il codice adatta la retta sui dati train e produce previsioni per le durate presenti nel test. Lo scarto fra attesa osservata e prevista viene poi riassunto mediante RMSE e MAE, che attribuiscono peso diverso agli errori grandi. Le misure riguardano gli 82 eventi separati. Una modifica del modello suggerita dai risultati del test richiederebbe un ulteriore campione indipendente per una nuova valutazione finale.''',formula=r'RMSE=\sqrt{\frac1{82}\sum_i(y_i-\widehat y_i)^2}\\MAE=\frac1{82}\sum_i|y_i-\widehat y_i|',codice=c,richiamo='Il test valuta una procedura definita; il suo riutilizzo per scegliere la procedura modifica il disegno.',origine='P04:18,20,28')
p('Osservato e previsto rendono visibili gli scarti',
'''Il diagramma confronta ogni attesa osservata con la previsione corrispondente, adottando la stessa scala sui due assi. La bisettrice rappresenta previsione esatta, mentre la distanza verticale rende leggibili sovrastime e sottostime. La presenza dei due addensamenti resta visibile anche negli eventi separati. Una correlazione elevata fra osservato e previsto sarebbe insufficiente a descrivere accuratezza e calibrazione, poiché potrebbe convivere con errori sistematici; per questo il confronto viene accompagnato da misure nella scala dei minuti.''',figura='P04/F05',didascalia='Ottantadue eventi di verifica. Bisettrice: previsione uguale all’osservazione; rapporto unitario fra gli assi.',richiamo='La valutazione predittiva richiede errori espressi nella scala della risposta, oltre all’associazione grafica.',origine='P04:19')
p('Il miglioramento viene quantificato in minuti',
'''Sul campione di verifica, la RMSE della previsione costante è circa 12,768 minuti, mentre quella della retta è circa 5,850 minuti. La MAE passa rispettivamente da circa 11,016 a 4,941 minuti. La durata fornisce quindi informazione predittiva utile entro questo esperimento e la separazione dichiarata. La grandezza del miglioramento rimane riferita a questi eventi e alle condizioni di scambiabilità, mentre la valutazione di utilità operativa richiederebbe soglie di errore rilevanti e dati cronologici nuovi.''',figura='P04/F06',didascalia='RMSE calcolata sugli stessi 82 eventi. La media di riferimento proviene esclusivamente dal train.',richiamo='Il guadagno predittivo viene espresso rispetto a un riferimento e a un dominio di valutazione dichiarati.',origine='P04:20,23–24')
p('La copertura viene osservata nel test',
'''Ottanta delle ottantadue attese ricadono nei rispettivi intervalli predittivi classici al 95%, producendo una copertura osservata di circa 97,56%. La figura ordina gli eventi per previsione e rende riconoscibili le due osservazioni esterne alla fascia. Questa proporzione costituisce una verifica empirica su un campione limitato, soggetta a variabilità e alle condizioni della separazione. La vicinanza al livello nominale non garantisce la medesima copertura per eventi futuri acquisiti con protocolli o condizioni del sistema differenti.''',formula=r'\widehat C=\frac1{82}\sum_i\mathbf1\{L_i\leq y_i\leq U_i\}=\frac{80}{82}',figura='P04/F08',didascalia='Eventi ordinati per previsione, senza significato cronologico. Ocra: due osservazioni esterne alla fascia.',richiamo='La copertura nominale è una proprietà della procedura sotto ipotesi; quella osservata è una proporzione campionaria.',origine='P04:21')
m.sezione_nuova('Struttura interna e discussione')
p('Le pendenze interne differiscono da quella globale',
'''Dividendo il solo campione di adattamento alla durata didattica di tre minuti, le pendenze risultano circa 5,588 e 4,328 nei gruppi di 72 e 118 eventi. Entrambe sono inferiori alla pendenza globale, circa 10,898, che incorpora anche la separazione fra addensamenti. Il confronto descrive una sensibilità dell’associazione e non assegna automaticamente uno stato fisico ai due gruppi. La soglia non viene scelta attraverso il test e le rette separate non sostituiscono retroattivamente la procedura già valutata.''',figura='P04/F07',didascalia='Rette entro due intervalli di durata, sul solo train. La soglia di tre minuti è un criterio descrittivo dichiarato.',richiamo='L’associazione complessiva può riflettere sia variazioni interne sia differenze fra gruppi.',origine='P04:22,29')
p('Consegna: distinguere effetto medio e previsione',
'''La relazione presenta fonte, separazione, grafici del train, pendenza con intervalli, residui, confronto predittivo e copertura. L’esercizio chiede quale intervallo utilizzare per la media degli eventi a una durata fissata e quale per un singolo nuovo evento, motivando il termine aggiuntivo nella varianza. Una seconda discussione identifica la fuga di informazione introdotta dalla media del test. La conclusione mantiene distinti associazione nel campione, generalizzazione interna e requisiti di una previsione cronologica applicata al sistema reale.''',destra='R/P04_figure.R conserva le previsioni per identificativo e i calcoli della covarianza HC3. I dati e il piano di separazione si trovano in dati/progetti. Il progetto raccorda regressione, intervalli predittivi e validazione dei moduli M07, M10 e M16.',richiamo='La forza della conclusione deriva dal collegamento fra bersaglio, informazione disponibile e disegno della verifica.',fonti='R datasets: faithful; statsmodels, HC3_se',origine='P04:23–30')
m.salva()
